 t=time.monotonic();assert not(ROOT/'runtime/STOP').exists();out=ROOT/'validation/integrated'/sys.argv[1];out.mkdir(exist_ok=False);shutil.copyfile(__file__,out/'verifier.py');src=ROOT/'validation/integrated'/sys.argv[2]/'summary.json';s=json.loads(src.read_text());c=np.load(REPO/s['output']['path']);P=sparse.load_npz(REPO/s['physical_P']['path']);A=sparse.load_npz(REPO/s['physical_A']['path']);p=np.load(REPO/s['problem']['path']);eq=np.isfinite(p['upper'])&(p['lower']==p['upper']);ine=~eq;V=c['V'];x=c['before_x'];dx=V@c['coefficients'];y=c['dual'];force=P@x+p['q'];gt=float(force@dx);curv=float(dx@(P@dx));alpha=min(1.,-gt/curv) if gt<0 and curv>0 else 1.;z=x+alpha*dx;sl=A@z-p['lower'];res=P@z+p['q']+A.T@y;obj=lambda v:float(.5*v@(P@v)+p['q']@v);pr=max(float(np.max(np.maximum(-sl[ine],0))),float(np.max(abs(sl[eq]))));accepted=bool(np.all(np.isfinite(z)) and pr<1e-10 and gt<0 and obj(z)<=obj(x)+1e-4*alpha*gt);m=dict(primal_mm=pr,stationarity_N=float(np.max(abs(res))),gauge_N=float(np.max(abs(y[eq]))),RootY_gamma_stationarity_N=float(abs(y[2175])),sign_N=float(np.max(np.maximum(y[ine],0))),complementarity_Nmm=float(np.max(abs(sl[ine]*y[ine]))),reduced_stationarity=float(np.max(abs(V.T@res))),objective_before_Nmm=obj(x),objective_proposed_Nmm=obj(z));qualified=accepted and all(m[k]<1e-8 for k in ['stationarity_N','gauge_N','RootY_gamma_stationarity_N','sign_N','complementarity_Nmm']);cad=json.loads((REPO/s['candidate']['path']).read_text());checks=dict(candidate_hash=sha(REPO/s['candidate']['path'])==s['candidate']['SHA256'],all78part_hashes=len(cad['part_references'])==78 and all(sha(REPO/r['path'])==r['SHA256'] for r in cad['part_references'].values()),output_hash=sha(REPO/s['output']['path'])==s['output']['SHA256'],all2208rows=A.shape[0]==2208,all37rigid_modes=s['retained_rigid_modes']==37,unmodified_original_H=np.max(abs(c['H']-V.T@(P@V)))<1e-7,unmodified_original_affine_g=np.max(abs(c['g']-V.T@force))<1e-10,all_original_cone_rows=np.max(abs(c['B']-A@V))<1e-10,direction_reproduced=np.max(abs(dx-c['direction']))<1e-12,proposal_reproduced=np.max(abs(z-c['proposed_x']))<1e-12,acceptance_reproduced=accepted==bool(s['accepted_linear_steps']),saved_state_reproduced=np.max(abs(c['after_x']-(z if accepted else x)))<1e-12,physical_residual_reproduced=np.max(abs(res-c['physical_residual']))<1e-10,physical_qualification_reproduced=qualified==s['physical_KKT_qualified'],no_support_update=s['actual_support_updates']==0,zero_physical_regularization=s['physical_regularization']==0)
 # Deliberate incorrect sign/affine/row pullbacks must change full residual.
 controls=dict(wrong_dual_sign_N=float(np.max(abs((P@z+p['q']-A.T@y)-res))),wrong_affine_N=float(np.max(abs(-p['q']-p['q']))));j=int(np.argmax(abs(y)));controls['omitted_largest_dual_row']=j;controls['omitted_row_force_N']=float(np.max(abs(A.getrow(j).toarray().ravel()*y[j])));checks['sign_control_detected']=controls['wrong_dual_sign_N']>1e-8;checks['affine_control_detected']=controls['wrong_affine_N']>1e-8;checks['row_control_detected']=controls['omitted_row_force_N']>1e-8
 ok=all(checks.values());dump(out/'summary.json',dict(status='ACTUAL_P1_CONIC_RITZ_AUDIT_PASS' if ok else 'ACTUAL_P1_CONIC_RITZ_AUDIT_FAIL',candidate=s['candidate'],source=ref(src),verifier=ref(out/'verifier.py'),checks={k:bool(v) for k,v in checks.items()},metrics=m,negative_controls=controls,physical_KKT_qualified=bool(qualified),accepted_linear_steps=int(accepted),actual_support_updates=0,accepted_equilibria=0,newly_qualified_system_gate_ids=[],whole_system_release=False,elapsed_s=time.monotonic()-t,limitations=['Audit PASS verifies saved numerical evidence, never product equilibrium or release. Search subspace may leave large orthogonal physical residual. Original nonlinear field unchanged.']));print(json.dumps(dict(checks=checks,metrics=m,controls=controls),default=bool));raise SystemExit(0 if ok else 2)
